  "terms": {"deathTitle": "***  SIGNAL LOST  ***", "deathLine": "You sank to the bottom as No. {n}.", "causeLabel": "Cause of signal loss", "deathWord": "Signals lost", "itemsKept": "Your gear stays clipped to the suit's belt. The next you may pick it up.", "shelf": "Sunken Numbers", "shelfLine": "No. {n}", "knowledge": "Dive Log", "knowledgeUnit": "Entries", "knowledgeShort": "Log", "terminal": "Underwater Radio", "terminalShort": "Radio", "terminalPrompt": "Enter the words to transmit.", "terminalCost": 1, "notFound": "No response.", "retry": "Open your eyes again", "start": "Open your eyes anew", "classPrompt": "Who were you?", "descend": "Go up", "stairs": "A rusted ladder leads upward.", "challenge": "Face it", "doors": "Several exits gape open from this section.", "remainsTag": "Remains", "starve": "You can't breathe.", "starveCause": "Ran out of oxygen", "lightOut": "Your lamp flickers out.", "lastRoom": "Little of this depth remains.", "toEnd": "To the end of this depth", "seenNone": "(The dive log has no record of this one.)", "newKnow": "[DIVE LOG] A new entry has been added.", "fightCmds": ["Attack", "Guard", "Item", "Swim away"], "enemyHp": "Left", "confirmClass": "Wake with this memory", "madness": "(Voices you don't know are mixed into the radio static.)", "madState": "<CROSSTALK>", "darkState": "<LAMP OUT>", "starveState": "<HYPOXIA>", "blindDoor": "...Your lamp is out. You can't see a thing", "lowFood": "Oxygen nearly gone", "lowLight": "Battery running thin", "fightDeath": "Dragged under by {enemy}", "mindHit": "Static floods into your head.", "mindOver": "Pain floods into your emptied head.", "drainHit": "Your lamp's light is being eaten.", "remainsTake": "Strip the gear and take it", "remainsLeave": "Lay the suit gently against the rock", "doorKinds": {"fight": "Presence", "shop": "Supply", "rest": "Rest", "treasure": "Stores", "omen": "Unease", "other": "Section"}},
  "help": ["- Each section you pass costs 1 Oxygen and 1 Battery.", "  Out of oxygen, you can't breathe, and your Health wears down.", "  Out of battery, your lamp dies and you can't see past the exits.", "- A check succeeds if 2D6 + stat meets the target.", "  The odds are shown on each choice. If you fail, you can spend", "  Luck to reroll. Red checks cannot be rerolled.", "- At 0 Mind you panic, and may do something other than", "  what you chose. In combat, panic costs you Health.", "- Enemies repeat their moves in a fixed order. Read the signs.", "  A move you have seen stays in the log, so you can read ahead.", "- Over the radio, you can send words you saw or heard below.", "  It costs 1 Battery. What comes back, you won't know until you send.", "- If you sink, you lose your gear and your body.", "  Only what you learned stays in the dive log.", "  Where you sank, the suit of the previous you will remain.", "- Your goal is the surface."],
  "remains": {"door": "An empty diving suit. \"No. 3\" on the chest.", "text": "A suit with the same number is snagged on a rock.\nIt is empty. There is a scrawl on the slate at its waist.\n\"{cls}. {cause}.\"\nIt is your handwriting.", "take": "You undo the gear clasps and open the belt pouch.\nWhat the previous you carried is still warm.", "leave": "You lay the suit gently against the rock.\nFor the next you. Your luck seems to turn, just a little."},
